class NomSectorSalarial extends BaseNomSectorSalarial {

    /**
     * Obtener un listado de los datos de los sectores salariales.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
	 *
     * @return array    Listado de los datos de los sectores salariales.
     */
    public static function obtenerListadoSectores($inicio = 0, $limite = 1000) {

        //Devolviendo el listado de sectores salariales en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomSectorSalarial')
				->orderBy('denominacion')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray():
                $query->from('NomSectorSalarial')
				->orderBy('denominacion')
                ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de sectores salariales.
     * 
     * @return int      Cantidad total de sectores salariales.
     */
    public static function obtenerCantidadTotalSectores() {

        //Devolviendo la cantidad total de sectores salariales.
        return Doctrine_Query::create()->select('COUNT(idsectorsalarial) AS cantidad')
                        ->from('NomSectorSalarial')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el sector salarial dado el identificador.
     * 
     * @param $idsector             Identificador del sector salarial.
     * @return NomSectorSalarial    Objeto sector salarial (clase del dominio).
     */
    public static function obtenerObjSectorDadoId($idsector) {
        return Doctrine::getTable('NomSectorSalarial')->find($idsector);
    }

    /**
     * Obtener todos los sectores salariales.
     * 
     * @return array    Listado de los datos de los sectores salariales.
     */
    public static function obtenerTodosSectores() {

        //Devolviendo el listado de sectores salariales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomSectorSalarial')
				->orderBy('denominacion')
                ->fetchArray();
    }
    
	/**
     * Obtener si existe un sector salarial a partir de la denominaci�n y la abreviatura.
     * 
	 * @param int $idsector    		Identificador del sector salarial.
	 * @param string $abrev    	 	Abreviatura del sector salarial.
     * @param string $denom    	 	Denominaci�n del sector salarial.
	 *
     * @return boolean    			Si existe el sector salarial.
     */
    public static function existeSectorSalarial($idsector, $abrev, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idsectorsalarial) AS cantidad')
                        ->from('NomSectorSalarial');
		if($abrev){
			$query->addWhere("abreviatura ilike ?", $abrev);
		}
		if($denom){
			$query->addWhere("denominacion ilike ?", $denom);
		}				
		if($idsector){
			$query->addWhere('idsectorsalarial <> ?', $idsector);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	
	
	
	
	
	
	
	
	
	
	
	
/************************************VER DESDE AQUI******************************************/	
    public static function existeDenominacion($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSectorSalarial p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function existeAbreviatura($abreviatura) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSectorSalarial p')
                ->where("p.abreviatura=?", array($abreviatura))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function obtenerDenominacionXId($idsectorsalarial) {
        return Doctrine_Query::create()->select('p.denominacion AS denominacion')
                        ->from('NomSectorSalarial p')
                        ->where('p.idsectorsalarial = ?', array($idsectorsalarial))
                        ->fetchOne()
                        ->denominacion;
   }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idsectorsalarial = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomSectorSalarial')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idsectorsalarial)) {
                $query->andWhere("idsectorsalarial <> ?", $idsectorsalarial);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }

}
